pub(super) fn lookup(language: &str, key: &str) -> Option<&'static str> {
    let index = KEYS.binary_search(&key).ok()?;
    let values = match language { "ja" => JA, "ko" => KO, "zh-CN" => ZH_CN, _ => EN };
    values.get(index).copied()
}
